## Code Example

```javascript
interface Report { date: string; userId: string; metrics: any }
interface Formatter { format(r: Report): string }
class JSONFormatter implements Formatter { format(r: Report) { return JSON.stringify(r) } }
class CSVFormatter implements Formatter { format(r: Report) { /* simple csv */ } }
class XMLFormatter implements Formatter { format(r: Report) { /* simple xml */ } }
class FormatterRegistry {
  private map = new Map<string, ()=>Formatter>();
  private last?: Formatter;
  register(name: string, mime: string, creator: ()=>Formatter) {
    this.map.set(mime, creator);
  }
  resolve(mime: string): Formatter {
    const creator = this.map.get(mime);
    this.last = creator ? creator() : new JSONFormatter();
    return this.last;
  }
}
```

